import json
G=[[0]*30 for _ in range(17)]
shape=[[(0,0),(0,1),(0,2),(0,3),(0,4)],[(1,2)],[(2,1),(2,2),(2,3)],[(3,0),(3,1),(3,2),(3,3),(3,4)],[(4,2)]]
for color,left in [(3,2),(1,9),(4,14),(8,21)]:
    for dy,cells in enumerate(shape):
        for dx in cells:
            G[7+dy][left+dx]=color
print([len(r) for r in G])
print(json.dumps(G,separators=(',',':')))

